import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextLong()) {
            long n = scanner.nextLong();
            int k = scanner.nextInt();

            List<Long> state = new ArrayList<>();
            for (int i = 0; i < k + 3; i++) {
                state.add(0L);
            }
            state.set(k, 1L);
            state.set(k + 1, 1L);
            state.set(k + 2, 1L);

            long power_of_k = 1;
            int digit_count = 0;
            while (power_of_k <= n / k) {
                power_of_k *= k;
                digit_count++;
            }

            List<List<Long>> P = new ArrayList<>();
            for (int i = 0; i <= digit_count; i++) {
                List<Long> row = new ArrayList<>();
                for (int j = 0; j < k + 3; j++) {
                    row.add(0L);
                }
                P.add(row);
            }

            for (int i = 0; i < k; i++) {
                P.get(0).set(i, 0L);
            }
            P.get(0).set(k, 1L);
            P.get(0).set(k + 1, 1L);
            P.get(0).set(k + 2, 1L);

            long offset = 0;
            int d_idx = digit_count;
            while (power_of_k > 0) {
                long t = (n - offset) / power_of_k;
                for (long j = 0; j < t; j++) {
                    int s = 0; // dummy
                    for (int i = 0; i < k; i++) {
                        state.set(i, state.get(i) + s);
                    }
                    offset += power_of_k;
                }
                power_of_k /= k;
                d_idx--;
            }
            System.out.println(state.get(k + 1));
        }
        scanner.close();
    }
}
